'use client';

/**
 * "Change sizes" for a SolidCraft model: every named size the model was built from, as a field the
 * buyer edits, a plain list of what will change, and one button that makes the next version.
 * Nothing is regenerated by Make AI: the CAD worker rebuilds the stored model with the new values,
 * and the result is a DRAFT version the buyer approves before any quote, like any model.
 *
 * Patterns (Mobbin, Nov 2026; recorded in workflows/10-frontend-mobbin-design.md):
 * - Krea AI object panel: a labelled numeric field per value, unit beside it, next to the 3D view.
 * - GitHub "Files changed" / ChatGPT turn summary: what changes, old -> new, before you commit it.
 * - Wabi version rows: each change becomes a version with its own chip.
 */
import { useMemo, useState } from 'react';
import { ArrowRight, Ruler } from 'lucide-react';
import type { MakeIt3dRecordView } from '@/contracts/make-it-3d';
import { SolidcraftExpression } from '@/contracts/text-to-cad';
import { Button } from '@/components/ui/button';
import { Field, TextInput } from '@/components/ui/field';
import { cn } from '@/lib/utils';

type Parameter = MakeIt3dRecordView['parameters'][number];

const norm = (v: string) => v.trim().replace(/\s+/g, ' ');

/** "overall length" -> "Overall length"; a bare name ("L") stays as it is. */
function labelOf(p: Parameter): string {
    const c = p.comment.trim();
    return c ? c.charAt(0).toUpperCase() + c.slice(1) : p.name;
}

/** The value as the buyer types it: the engine's expression ("80 mm"), else the number and unit. */
function initialValue(p: Parameter): string {
    if (p.expression) return p.expression;
    return p.value === null ? '' : `${p.value}${p.unit ? ` ${p.unit}` : ''}`;
}

export function SizesCard({
    record,
    nextVersion,
    busy,
    error,
    onSubmit,
}: {
    record: MakeIt3dRecordView;
    nextVersion: number;
    busy: boolean;
    error: string | null;
    onSubmit: (changes: Record<string, string>) => void;
}) {
    const start = useMemo(() => Object.fromEntries(record.parameters.map((p) => [p.name, initialValue(p)])), [record.parameters]);
    const [values, setValues] = useState<Record<string, string>>(start);
    const [touched, setTouched] = useState<Record<string, boolean>>({});

    const problems = Object.fromEntries(
        record.parameters.map((p) => {
            const r = SolidcraftExpression.safeParse(values[p.name] ?? '');
            return [p.name, r.success ? null : (r.error.issues[0]?.message ?? 'Check this value.')];
        }),
    ) as Record<string, string | null>;
    const changed = record.parameters.filter((p) => norm(values[p.name] ?? '') !== norm(start[p.name] ?? ''));
    const valid = changed.every((p) => !problems[p.name]);

    if (record.parameters.length === 0) return null;
    return (
        <section aria-labelledby="make3d-sizes-heading" className="rounded-xl bg-graphite-850 p-4 ring-1 ring-inset ring-graphite-700" data-testid="make3d-sizes">
            <h3 id="make3d-sizes-heading" className="flex items-center gap-2 text-sm font-semibold">
                <Ruler className="h-4 w-4" aria-hidden /> Change sizes
            </h3>
            <p className="mt-1 text-sm text-fg-muted">Type new values. The model is rebuilt with them as version {nextVersion}; nothing is redrawn by AI.</p>
            <form
                className="mt-3"
                onSubmit={(e) => {
                    e.preventDefault();
                    setTouched(Object.fromEntries(record.parameters.map((p) => [p.name, true])));
                    if (!changed.length || !valid) return;
                    onSubmit(Object.fromEntries(changed.map((p) => [p.name, norm(values[p.name] ?? '')])));
                }}
            >
                <fieldset disabled={busy} className="grid gap-3">
                    <legend className="sr-only">Sizes of this model</legend>
                    {record.parameters.map((p) => (
                        <Field key={p.name} label={labelOf(p)} hint={p.comment ? `${p.name} · was ${start[p.name]}` : `was ${start[p.name]}`} error={touched[p.name] ? problems[p.name] : null}>
                            {({ id, describedBy, invalid }) => (
                                <TextInput
                                    id={id}
                                    aria-describedby={describedBy}
                                    aria-invalid={invalid}
                                    inputMode="decimal"
                                    autoComplete="off"
                                    spellCheck={false}
                                    value={values[p.name] ?? ''}
                                    onChange={(e) => setValues((v) => ({ ...v, [p.name]: e.target.value }))}
                                    onBlur={() => setTouched((t) => ({ ...t, [p.name]: true }))}
                                    className="font-mono text-base md:text-sm"
                                    data-testid={`make3d-size-${p.name}`}
                                />
                            )}
                        </Field>
                    ))}
                </fieldset>

                {changed.length > 0 && (
                    <div className="mt-4 border-t border-graphite-700 pt-3" data-testid="make3d-size-changes">
                        <p className="text-xs font-semibold uppercase tracking-wide text-fg-subtle">
                            {changed.length} {changed.length === 1 ? 'change' : 'changes'}
                        </p>
                        <ul className="mt-2 space-y-1 text-sm">
                            {changed.map((p) => (
                                <li key={p.name} className="flex flex-wrap items-center gap-1.5">
                                    <span className="font-medium">{labelOf(p)}</span>
                                    <span className="font-mono text-fg-muted line-through">{start[p.name]}</span>
                                    <ArrowRight className="h-3.5 w-3.5 text-fg-subtle" aria-label="to" />
                                    <span className={cn('font-mono', problems[p.name] ? 'text-ember' : 'text-signal')}>{norm(values[p.name] ?? '')}</span>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}

                {error && (
                    <p className="mt-3 text-sm text-ember" role="alert" data-testid="make3d-sizes-error">
                        {error}
                    </p>
                )}
                <div className="mt-4 flex flex-col gap-2">
                    <Button type="submit" className="min-h-11 w-full" loading={busy} disabled={!changed.length || !valid} data-testid="make3d-sizes-submit">
                        Make version {nextVersion}
                    </Button>
                    {changed.length > 0 && !busy && (
                        <Button type="button" variant="ghost" className="min-h-11 w-full" onClick={() => setValues(start)} data-testid="make3d-sizes-reset">
                            Undo changes
                        </Button>
                    )}
                </div>
            </form>
        </section>
    );
}
